            solution: 'static Dictionary<string, int> RäknaOrd(List<string> ord)\n{\n    Dictionary<string, int> antal = new Dictionary<string, int>();\n    foreach (string o in ord)\n    {\n        if (antal.ContainsKey(o))\n        {\n            antal[o]++;\n        }\n        else\n        {\n            antal[o] = 1;\n        }\n    }\n    return antal;\n}',
